Movie.where{
      genre{
        name in favoriteGenreNames
      }
      deleted != true
    }

TvShow.where{
      genre{
        name in favoriteGenreNames
      }
      episodes.size() > 0
      deleted != true
    }

TvShow.where {
      deleted != true
      apiId != null
      (poster_image == null || backdrop_image == null)
      if(ids){
        id in ids
      }
    }

Movie.where {
      deleted != true
      apiId != null
      (poster_image == null || backdrop_image == null)
      if(ids){
        id in ids
      }
    }

WatchlistEntry.where {
      user == currentUser
      profile == currentProfile
      isDeleted == false
      video != null || tvShow != null
    }

genres.each{ metaGenre ->
        log.info("genre: " + metaGenre.name + " for movie " + movie.title)
        Genre genre = Genre.findByApiId(metaGenre.id)
        if(!genre){
          log.error("Genre missing!: " + metaGenre.name)
          return
        }
        movie.addToGenre(genre)
      }

genres.each{ metaGenre ->
        log.info("genre: " + metaGenre.name + " for tvShow " + tvShow.name)
        Genre genre = Genre.findByApiId(metaGenre.id)

        if(!genre){
          log.error("Genre missing!: " + metaGenre.name)
          return
        }

        tvShow.addToGenre(genre)
      }

User.where {
      def currentUser = User
      not{
        exists Profile.where {
          def profile = Profile
          def profileUser = user
          currentUser.id == profileUser.id
        }.id()
      }
    }

User.where{
      def currentUser = User
      exists ViewingStatus.where {
        def viewingStatus = ViewingStatus
        def viewingStatusUser = user
        currentUser.id == viewingStatusUser.id
      }.id()
    }

ViewingStatus.where{
      user == currentUser
      video == video
      profile == params.profile
    }
